import{_ as r,a0 as s,w as p,s as u,ao as l,I as i,x as o,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"為減少視覺錯誤信息，Adobe 推出了開源工具包 | LCTT x X-CMD","titleTemplate":false,"description":"為減少視覺錯誤信息，Adobe 推出了開源工具包 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為減少視覺錯誤信息，Adobe 推出了開源工具包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為減少視覺錯誤信息，Adobe 推出了開源工具包 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220614 Adobe Launches Open Source Toolkit To Contain Visual Misinformation","title":"為減少視覺錯誤信息，Adobe 推出了開源工具包","tag":"202206","desc":""},"relativePath":"202206/20220614 Adobe Launches Open Source Toolkit To Contain Visual Misinformation.md","filePath":"[post].md"}'),d={name:"202206/20220614 Adobe Launches Open Source Toolkit To Contain Visual Misinformation.md"};function m(f,t,b,T,A,C){const e=s("Link");return p(),u("div",null,[t[15]||(t[15]=l('<h1 id="為減少視覺錯誤信息-adobe-推出了開源工具包" tabindex="-1">為減少視覺錯誤信息，Adobe 推出了開源工具包 <a class="header-anchor" href="#為減少視覺錯誤信息-adobe-推出了開源工具包" aria-label="Permalink to “為減少視覺錯誤信息，Adobe 推出了開源工具包”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/19/105844yauuhdz1u1189ffr.jpg" alt=""></p><p>Adobe 設想的是為網絡上充斥的照片和視頻標註關於它們的來源。該公司的主要目標是減少視覺錯誤信息的傳播，不過，該系統也可以使那些“希望將自己的名字與工作關聯起來”的內容創作者受益。</p><p>Adobe 在 2019 年首次宣佈了其 <ruby>內容真實性計劃<rt>Content Authenticity Initiative</rt></ruby>（CAI）項目，此後，它發佈了一份關於實現該目標的技術白皮書，將該系統集成了到自己的軟件中，並與新聞編輯室和硬件製造商展開了合作，以幫助普及其願景。</p><p>現在，該公司發佈了一個由三部分組成的開源工具包，從而把該技術交到開發人員手中，並投入使用。Adobe 的新開源工具包括一個用於開發“在瀏覽器中顯示內容憑據”的 JavaScript SDK、一個命令列實用程序，和一個用於開發桌面應用程序、移動應用程序和其他應用的 Rust SDK，以創建、查看和驗證嵌入式內容憑據。</p><p>眾所周知，照片的 EXIF 數據中記錄了有關光圈和快門速度的信息，這個新標準也採用了這種方式，它還記錄有關文件創建的信息，例如文件的創建和編輯方式。如果該公司的共同願景成真，這些 Adobe 稱之為“內容憑證”的元數據，將在社交媒體平台、圖像搜索平台、圖像編輯器、搜索引擎中廣泛可見。</p><p>C2PA 是 Adob​​e 的 CAI 與 微軟、索尼、英特爾、推特以及 BBC 等合作伙伴的合作成果。華爾街日報、尼康和美聯社最近也加入了 Adob​​e 的這個計劃，即將 <ruby>內容認證技術<rt>content authentication</rt></ruby> 更加廣泛地應用。</p><p>有了這些新工具，社交媒體平台就可以使用 Adob​​e 的 JavaScript SDK，快速讓平台上的所有圖像和視頻顯示內容憑據，這些憑據將會在鼠標懸停時，顯示為右上角的一個圖標。因此，無需專門的團隊和更大的軟件構建，該實施可以由幾個開發人員在幾周內完成。</p><p>CAI 的主要目標是打擊互聯網上的視覺錯誤信息，比如那些扭曲烏克蘭戰爭的舊圖片的重新傳播，或是臭名昭著的南希·佩洛西的“廉價假貨”。不過，數字監管鏈也可能使“作品被盜或出售”的內容創作者受益，這個問題多年來一直困擾着視覺藝術家，現在也正在 NFT 市場引發問題。</p><p>根據 Parsons 的説法，CAI 還引起了那些“製作合成圖像和視頻”的公司的巨大興趣。公司可以將原始元數據嵌入到我們從 DALL-E 等模型中看到的那種 AI 創作中，從而確保它提供的合成圖像不會輕易被誤認為是真實的東西。</p><hr>',11)),i("p",null,[t[1]||(t[1]=o("via: ",-1)),n(e,{href:"https://www.opensourceforu.com/2022/06/adobe-launches-open-source-toolkit-to-contain-visual-misinformation/"},{default:a(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/06/adobe-launches-open-source-toolkit-to-contain-visual-misinformation/",-1)])]),_:1})]),i("p",null,[t[6]||(t[6]=o("作者：",-1)),n(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 選題：",-1)),n(e,{href:"https://github.com/lkxed"},{default:a(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 譯者：",-1)),n(e,{href:"https://github.com/lkxed"},{default:a(()=>[...t[4]||(t[4]=[o("lkxed",-1)])]),_:1}),t[9]||(t[9]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:a(()=>[...t[11]||(t[11]=[o("Linux中國",-1)])]),_:1}),t[14]||(t[14]=o(" 榮譽推出",-1))])])}const h=r(d,[["render",m]]);export{k as __pageData,h as default};
